func joinRoutePaths(prefix, route string) string {
	if prefix == "" || prefix == "/" {
		if route == "" {
			return "/"
		}
		if strings.HasPrefix(route, "/") {
			return route
		}
		return "/" + route
	}
	if route == "" || route == "/" {
		if strings.HasPrefix(prefix, "/") {
			return prefix
		}
		return "/" + prefix
	}
	left := strings.TrimRight(prefix, "/")
	right := strings.TrimLeft(route, "/")
	if !strings.HasPrefix(left, "/") {
		left = "/" + left
	}
	return left + "/" + right
}

