L624: 		/* DOS like systems */
L625: 		c = cf->do_fgetc(cf);
L626: 		if (c != '\n') {
L627: 			if (c != EOF)
L628: 				cf->do_ungetc(c, cf);
L629: 			c = '\r';
L630: 		}
L631: 	}
L632: 	if (c != EOF && ++cf->total_len > INT_MAX) {
L633: 		/*
L634: 		 * This is an absurdly long config file; refuse to parse
L635: 		 * further in order to protect downstream code from integer
L636: 		 * overflows. Note that we can't return an error specifically,
L637: 		 * but we can mark EOF and put trash in the return value,
L638: 		 * which will trigger a parse error.
L639: 		 */
L640: 		cf->eof = 1;
L641: 		return 0;
L642: 	}
L643: 
L644: 	if (c == '\n')
L645: 		cf->linenr++;
L646: 	if (c == EOF) {
L647: 		cf->eof = 1;
L648: 		cf->linenr++;
L649: 		c = '\n';
L650: 	}
L651: 	return c;
