     8	// WorktreeMatchesHEAD reports whether the working tree's indexable content is
     9	// byte-identical to the committed HEAD tree.
    10	//
    11	// It is the precondition that lets a caller reuse a tree-keyed index cache for
    12	// a working-tree query: when nothing is modified, staged, deleted or untracked,
    13	// every file a working-tree walk can see is exactly the file HEAD records, so a
    14	// snapshot built from one is a snapshot of the other.
    15	//
    16	// The check is one `git status --porcelain --untracked-files=all` and is
    17	// deliberately conservative:
    18	//
    19	//   - it reports FALSE on any output at all — modified, staged, deleted,
    20	//     renamed, unmerged, untracked, or a dirty submodule;
    21	//   - `--untracked-files=all` is required, not optional: a working-tree walk
    22	//     indexes untracked-but-not-ignored files, so "no tracked modifications"
    23	//     alone would not make the two views equal;
    24	//   - files git ignores are excluded from BOTH sides (the provider's
    25	//     working-tree walk honours .gitignore), so an ignored build artifact
    26	//     changing cannot invalidate the equality. If the ignore rules themselves
    27	//     change so that a file stops being ignored, that file becomes untracked
    28	//     and this check turns false, which is the safe direction;
    29	//   - any error (not a git repository, git missing) reports FALSE with the
    30	//     error, never a hopeful TRUE.
    31	//
    32	// `--no-optional-locks` keeps this read-only probe from refreshing the index
    33	// and so from contending with a concurrent git command in the same repo.
    34	func WorktreeMatchesHEAD(ctx context.Context, repo string) (bool, error) {
    35		paths, err := WorktreeDirtyPaths(ctx, repo)
    36		if err != nil {
    37			return false, err
    38		}
    39		return len(paths) == 0, nil
    40	}
    41	
    42	// WorktreeDirtyPaths returns every repo-relative path that makes the working
    43	// tree differ from HEAD: modified, staged, deleted, renamed, unmerged, or
    44	// untracked-but-not-ignored. An empty slice means the two views are equal, so
    45	// WorktreeMatchesHEAD is exactly len(paths)==0.
    46	//
    47	// It exists so a caller can ask the sharper question "does anything that
    48	// differs actually affect what I build?". WorktreeMatchesHEAD answers only
    49	// "does anything differ at all", which disables a tree-keyed cache for a stray
    50	// .DS_Store or a compiled binary — files no indexer reads. The caller owns that
    51	// judgement because only it knows which paths it consumes; this function stays
    52	// purely factual.
    53	//
    54	// Both sides of a rename are reported, since a rename both removes the old path
    55	// and adds the new one.
    56	//
    57	// Ignored files are excluded (git omits them without --ignored), matching the
    58	// provider's working-tree walk, which honours .gitignore.
    59	func WorktreeDirtyPaths(ctx context.Context, repo string) ([]string, error) {
    60		// A repository with no commits has no HEAD tree to be equal to.
    61		if _, err := RevParse(ctx, repo, "HEAD"); err != nil {
    62			return nil, err
    63		}
    64		out, err := run(ctx, repo, "git",
    65			"--no-optional-locks", "status", "--porcelain", "--untracked-files=all", "-z")
    66		if err != nil {
    67			return nil, err
    68		}
    69		// -z emits NUL-terminated records "XY <path>". A rename or copy spends a
    70		// SECOND record on its source path, with no status prefix of its own, so it
    71		// must be consumed alongside the entry that introduced it rather than parsed
    72		// as a malformed status line.
    73		fields := strings.Split(out, "\x00")
    74		paths := make([]string, 0, len(fields))
    75		for i := 0; i < len(fields); i++ {
    76			field := fields[i]
    77			if len(field) < 4 || field[2] != ' ' {
    78				continue
    79			}
    80			status, path := field[:2], field[3:]
    81			if path != "" {
    82				paths = append(paths, path)
    83			}
    84			if strings.ContainsAny(status, "RC") && i+1 < len(fields) {
    85				i++
    86				if source := fields[i]; source != "" {
    87					paths = append(paths, source)
    88				}
    89			}
    90		}
    91		return paths, nil
    92	}
